"""Lightweight, separate library-search and conversational-question surfaces."""
import tkinter as tk
from tkinter import ttk
from tkinter.scrolledtext import ScrolledText


def build_views(app):
    search=app.search_tab;search.columnconfigure(0,weight=1);search.rowconfigure(2,weight=1)
    query=ttk.LabelFrame(search,text='Search the library',padding=10);query.grid(row=0,column=0,sticky='ew',pady=(0,8));query.columnconfigure(0,weight=1)
    app.search_query=tk.StringVar();entry=ttk.Entry(query,textvariable=app.search_query,font=('Segoe UI',11));entry.grid(row=0,column=0,sticky='ew',ipady=4)
    entry.bind('<Return>',lambda e:app.search() if not app.busy else None)
    row=ttk.Frame(query);row.grid(row=1,column=0,sticky='ew',pady=8)
    app.button(row,'Search library',app.search,side='left');app.button(row,'Browse sources',app.browse,side='left',padx=6)
    ttk.Button(row,text='Search syntax',command=app.search_help).pack(side='left',padx=6)
    app.filters_visible=tk.BooleanVar(value=False);ttk.Checkbutton(row,text='Search options',variable=app.filters_visible,command=app.toggle_filters).pack(side='right')
    app.relevance_question=tk.StringVar();ttk.Label(query,text='Rank results for this question (optional)').grid(row=2,column=0,sticky='w')
    ttk.Entry(query,textvariable=app.relevance_question).grid(row=3,column=0,sticky='ew',pady=(3,0))
    panel=ttk.LabelFrame(search,text='Search options',padding=10);panel.grid(row=1,column=0,sticky='ew',pady=(0,8));app.filter_panel=panel
    app.search_input_mode=tk.StringVar(value=app.raw.get('search_input_mode','simple'));app.exact_count=tk.BooleanVar(value=False)
    ttk.Label(panel,text='Input').grid(row=0,column=0,sticky='w');ttk.Combobox(panel,textvariable=app.search_input_mode,values=('simple','advanced'),state='readonly',width=11).grid(row=0,column=1,padx=6)
    ttk.Checkbutton(panel,text='Count all matches',variable=app.exact_count).grid(row=0,column=2,columnspan=2,padx=12)
    app.date_field=tk.StringVar(value='added_at');app.after=tk.StringVar();app.before=tk.StringVar();app.sort=tk.StringVar(value='relevance')
    for col,label,var,values in [(0,'Date type',app.date_field,('added_at','modified_at','published_at')),(2,'Order',app.sort,('relevance','newest'))]:
        ttk.Label(panel,text=label).grid(row=1,column=col,sticky='w',pady=6);ttk.Combobox(panel,textvariable=var,values=values,state='readonly',width=14).grid(row=1,column=col+1,padx=6)
    for col,label,var in [(0,'After',app.after),(2,'Before',app.before)]:ttk.Label(panel,text=label).grid(row=2,column=col,sticky='w');ttk.Entry(panel,textvariable=var,width=16).grid(row=2,column=col+1,padx=6)
    ttk.Label(panel,text='YYYY-MM-DD · date added is not publication date.').grid(row=3,column=0,columnspan=4,sticky='w',pady=(6,0));panel.grid_remove()
    app.workspace=ttk.Panedwindow(search,orient='horizontal');app.workspace.grid(row=2,column=0,sticky='nsew')
    results=ttk.LabelFrame(app.workspace,text='Reports',padding=8);app.workspace.add(results,weight=2)
    app.result_summary=tk.StringVar(value='Search or browse to see reports.');ttk.Label(results,textvariable=app.result_summary,wraplength=350).pack(anchor='w',pady=(0,6))
    table=ttk.Frame(results);table.pack(fill='both',expand=True)
    app.tree=ttk.Treeview(table,columns=('title','copies','date','preview'),displaycolumns=('title','copies','date'),show='headings',selectmode='browse')
    for name,label,width in [('title','Report',230),('copies','Copies',55),('date','Date',115),('preview','Text',250)]:app.tree.heading(name,text=label);app.tree.column(name,width=width,stretch=name=='title')
    app.tree.pack(side='left',fill='both',expand=True);scroll=ttk.Scrollbar(table,orient='vertical',command=app.tree.yview);scroll.pack(side='right',fill='y');app.tree.configure(yscrollcommand=scroll.set)
    app.tree.bind('<<TreeviewSelect>>',app.preview_result);app.tree.bind('<Double-1>',app.expand)
    pages=ttk.Frame(results);pages.pack(fill='x',pady=8)
    for label,command in [('More results',app.more_results),('Read source',app.read_document),('Next page',lambda:app.read_document(next_page=True))]:app.button(pages,label,command,side='left',padx=3)
    app.detail_tabs=ttk.Notebook(app.workspace);app.answer_tab=ttk.Frame(app.detail_tabs,padding=6);app.detail_tabs.add(app.answer_tab,text='Source');app.workspace.add(app.detail_tabs,weight=3)
    app.output=ScrolledText(app.answer_tab,wrap='word',font=('Segoe UI',10),width=35,height=8);app.output.pack(fill='both',expand=True)
    app.metrics=tk.StringVar();app.metrics_label=ttk.Label(search,textvariable=app.metrics,wraplength=1000);app.metrics_label.grid(row=3,column=0,sticky='ew',pady=4)
    app.ingest_bar=ttk.Progressbar(search,maximum=1);app.ingest_bar.grid(row=4,column=0,sticky='ew')
    app.show('Search with words or phrases, or browse your indexed reports. Use Search syntax for examples.')
    build_ask(app)


def build_ask(app):
    parent=app.ask_tab;parent.columnconfigure(0,weight=1);parent.rowconfigure(2,weight=1)
    top=ttk.Frame(parent);top.grid(row=0,column=0,sticky='ew',pady=(0,8))
    ttk.Label(top,text='Ask your library',font=('Segoe UI',14,'bold')).pack(side='left')
    app.button(top,'New conversation',app.new_conversation,side='right')
    ttk.Button(top,text='Details…',command=app.show_trace).pack(side='right',padx=8)
    status=ttk.Frame(parent);status.grid(row=1,column=0,sticky='ew')
    app.chat_status=tk.StringVar(value='Ask a question, then follow up in the same conversation.');app.reading_status=tk.StringVar()
    ttk.Label(status,textvariable=app.chat_status,font=('Segoe UI',10,'bold')).pack(anchor='w');ttk.Label(status,textvariable=app.reading_status,wraplength=950).pack(anchor='w',pady=(2,6))
    app.chat=ScrolledText(parent,wrap='word',font=('Segoe UI',11),padx=12,pady=12,state='disabled');app.chat.grid(row=2,column=0,sticky='nsew')
    app.chat.tag_configure('speaker',font=('Segoe UI',10,'bold'),foreground='#34516b')
    composer=ttk.Frame(parent,padding=(0,8));composer.grid(row=3,column=0,sticky='ew');composer.columnconfigure(0,weight=1)
    app.question=tk.StringVar();app.question_entry=ttk.Entry(composer,textvariable=app.question,font=('Segoe UI',11));app.question_entry.grid(row=0,column=0,sticky='ew',ipady=5)
    app.question_entry.bind('<Return>',lambda e:app.question_model() if not app.busy else None)
    button=ttk.Button(composer,text='Send',command=app.question_model);button.grid(row=0,column=1,padx=(8,0));app.controls.append(button)
    controls=ttk.Frame(parent);controls.grid(row=4,column=0,sticky='ew')
    modes=('quick','balanced','thorough');configured=app.raw.get('agent_options',{}).get('effort','legacy')
    app.effort=tk.StringVar(value=configured);app.effort_level=tk.DoubleVar(value=modes.index(configured) if configured in modes else 1);app.legacy_policy=tk.BooleanVar(value=configured=='legacy')
    ttk.Label(controls,text='Answer effort').pack(side='left');scale=ttk.Scale(controls,from_=0,to=2,variable=app.effort_level,command=app.effort_changed,length=180);scale.pack(side='left',padx=8)
    scale.bind('<ButtonRelease-1>',lambda e:scale.set(round(app.effort_level.get())))
    ttk.Label(controls,textvariable=app.effort,width=10).pack(side='left');ttk.Checkbutton(controls,text='Legacy comparison',variable=app.legacy_policy,command=app.effort_changed).pack(side='left',padx=8)
    steer=ttk.Frame(parent);steer.grid(row=5,column=0,sticky='ew',pady=(8,0));steer.columnconfigure(1,weight=1)
    app.steering_text=tk.StringVar();app.steering_status=tk.StringVar(value='You can guide an answer while it is running.')
    ttk.Label(steer,text='Guide this answer').grid(row=0,column=0,padx=(0,6));ttk.Entry(steer,textvariable=app.steering_text).grid(row=0,column=1,sticky='ew')
    ttk.Button(steer,text='Queue instruction',command=app.queue_steering).grid(row=0,column=2,padx=6);ttk.Label(steer,textvariable=app.steering_status).grid(row=1,column=0,columnspan=3,sticky='w',pady=4)
    app.trace_window=tk.Toplevel(app.root);app.trace_window.title('Conversation details');app.trace_window.geometry('900x650');app.trace_window.withdraw();app.trace_window.protocol('WM_DELETE_WINDOW',app.trace_window.withdraw)
    app.trace_choice=tk.StringVar(value='Current turn');app.trace_selector=ttk.Combobox(app.trace_window,textvariable=app.trace_choice,values=('Current turn',),state='readonly');app.trace_selector.pack(fill='x',padx=10,pady=8);app.trace_selector.bind('<<ComboboxSelected>>',app.select_trace)
    app.trace_tabs=ttk.Notebook(app.trace_window);app.trace_tabs.pack(fill='both',expand=True,padx=10,pady=(0,10))
    for label,name in [('Activity / turns','live'),('Thinking','thinking_live'),('Timing','timing_details')]:
        page=ttk.Frame(app.trace_tabs);app.trace_tabs.add(page,text=label);widget=ScrolledText(page,wrap='word',font=('Consolas',9),state='disabled');widget.pack(fill='both',expand=True);setattr(app,name,widget)
